// Generates src/ui/Icon.tsx from scripts/icons.json. Run: npm run gen:icons
// The generated file is committed, so a normal build never depends on this script.
import { readFileSync, writeFileSync } from "node:fs";

const icons = JSON.parse(
  readFileSync(new URL("./icons.json", import.meta.url), "utf8"),
);

const entries = Object.entries(icons)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([name, markup]) => {
    const jsx = markup
      .replaceAll(" class=", " className=")
      .replace(/className="spin"/, 'className="anim-spin"');
    return `  '${name}': <>${jsx}</>,`;
  })
  .join("\n");

const out = `// GENERATED by scripts/gen-icons.mjs from scripts/icons.json. Do not edit by hand.
import type { ReactNode } from 'react'

const shapes = {
${entries}
} satisfies Record<string, ReactNode>

export type IconName = keyof typeof shapes

type Props = {
  name: IconName
  size?: number
  className?: string
}

// All icons share one 24x24 stroke style and take their colour from the surrounding text.
export function Icon({ name, size = 20, className }: Props) {
  return (
    <svg
      aria-hidden="true"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
    >
      {shapes[name]}
    </svg>
  )
}
`;
writeFileSync(new URL("../src/ui/Icon.tsx", import.meta.url), out);
console.log(`wrote ${Object.keys(icons).length} icons`);
